import React, { useState, useContext, useEffect } from 'react';
import PetCard from './PetCard';
import PrimaryButton from './PrimaryButton';
import './Catalog.css';
import Header from '../header/Header';
import Footer from '../footer/Footer';
import { PetContext } from './PetContext';

const Catalog = () => {
  const {petsData} = useContext(PetContext);
  const [searchItem, setSearchItem] = useState("");
  const [filteredPets, setFilteredPets] = useState(petsData);
  const [count, setCount] = useState(0);
  const [sortOption, setSortOption] = useState("Choose one...");

  useEffect(() => {
    const applyFilters = () => {
      const trimmedSearchItem = searchItem.trim().toLowerCase();

      let updatedPets = petsData.filter((pet) =>
          pet.location.toLowerCase().includes(trimmedSearchItem)
      );

      if (sortOption !== "Choose one...") {
        updatedPets = sortPets(updatedPets, sortOption);
      }

      setFilteredPets(updatedPets);
    };

    applyFilters();
  }, [petsData, searchItem, sortOption]);


  const sortPets = (petsList, option) => {
    let sortedPets = [...petsList];
    switch (option) {
      case "Duration (Low - High)":
        sortedPets.sort((a, b) => a.duration - b.duration);
        break;
      case "Duration (High - Low)":
        sortedPets.sort((a, b) => b.duration - a.duration);
        break;
      case "Price (Low - High)":
        sortedPets.sort((a, b) => a.price - b.price);
        break;
      case "Price (High - Low)":
        sortedPets.sort((a, b) => b.price - a.price);
        break;
      case "Name (A - Z)":
        sortedPets.sort((a, b) => a.location.localeCompare(b.location));
        break;
      case "Name (Z - A)":
        sortedPets.sort((a, b) => b.location.localeCompare(a.location));
        break;
      default:
        break;
    }
    return sortedPets;
  };

  const handleSearch = (event) => {
    setSearchItem(event.target.value.toLowerCase());
  };

  const handleClear = () => {
    setSearchItem("");
    setSortOption("Choose one...");
    setFilteredPets(petsData);
  };

  const handleSort = (event) => {
    setSortOption(event.target.value);
  };

  const handleCount = () => {
    const total = filteredPets.reduce((partialSum, pet) => partialSum + pet.price, 0);
    setCount(total);
  };

  return (
      <>
        <Header />

        <div className="catalog-container">
          <div className="catalog-header">
            <PrimaryButton label="Add a Pet" onClick={() => {}} />

            <div className="search-bar">
              <input
                  type="text"
                  placeholder="Search..."
                  value={searchItem}
                  onChange={handleSearch}
              />
              <PrimaryButton label="Clear" onClick={handleClear} />
            </div>
          </div>

          <h2>Manage Pets</h2>
          <div className="sort-section">
            <label>Sort by:</label>
            <select value={sortOption} onChange={handleSort}>
              <option value="Choose one...">Choose one...</option>
              <option value="Duration (Low - High)">Duration (Low - High)</option>
              <option value="Duration (High - Low)">Duration (High - Low)</option>
              <option value="Price (Low - High)">Price (Low - High)</option>
              <option value="Price (High - Low)">Price (High - Low)</option>
              <option value="Name (A - Z)">Name (A - Z)</option>
              <option value="Name (Z - A)">Name (Z - A)</option>
            </select>
          </div>

          <div className="total-pets-section">
            <h3>Total Pets Value</h3>
            <div className="total-value">
              <PrimaryButton label="Count" onClick={handleCount} />
              <h4>Total: {count}</h4>
            </div>
          </div>

          <div className="product-list">
            {filteredPets.map(pet => (
                <PetCard key={pet.id} pet={pet} />
            ))}
          </div>
        </div>
        <Footer />
      </>
  );
};

export default Catalog;
